begin;
-- Reproduce managed Supabase: fgc_command cannot reach the auth schema at all.
revoke usage on schema auth from fgc_command;
revoke select on auth.sessions,auth.users from fgc_command;
insert into auth.users(id) values('00000000-0000-4000-8000-000000000001'),('00000000-0000-4000-8000-000000000002');
insert into auth.sessions(id,user_id) values('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001');
insert into auth.sessions(id,user_id,not_after) values('10000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000001',now()-interval '1 minute');
insert into auth.sessions(id,user_id) values('10000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000002');
insert into core.users(id,email) values('00000000-0000-4000-8000-000000000001','admin@example.invalid');
insert into core.events(id,name,active) values('20000000-0000-4000-8000-000000000001','Synthetic',true);
insert into core.user_event_roles values('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','admin');
create or replace function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERT: %',label;end if;end$$;
create or replace function pg_temp.expect_error(q text,expected text) returns void language plpgsql as $$begin execute q;raise exception 'EXPECTED_ERROR_NOT_THROWN';exception when others then if sqlerrm<>expected then raise exception 'Expected %, got %',expected,sqlerrm;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001"}',true);
select pg_temp.assert_true(api.me()->>'id'='00000000-0000-4000-8000-000000000001','live session resolves the actor without fgc_command reaching auth');
select pg_temp.assert_true(api.me()->'roles'='["admin"]'::jsonb,'roles load through the helper');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000002"}',true);
select pg_temp.expect_error($q$select api.me()$q$,'UNAUTHENTICATED');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000003"}',true);
select pg_temp.expect_error($q$select api.me()$q$,'UNAUTHENTICATED');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001"}',true);
select pg_temp.expect_error($q$select api.me()$q$,'UNAUTHENTICATED');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000002","session_id":"10000000-0000-4000-8000-000000000003"}',true);
select pg_temp.expect_error($q$select api.me()$q$,'FORBIDDEN');
select pg_temp.expect_error($q$select private.session_actor()$q$,'permission denied for function session_actor');
reset role;
select pg_temp.assert_true(not has_function_privilege('anon','private.session_actor()','EXECUTE'),'anon cannot call the helper');
select pg_temp.assert_true(not has_function_privilege('service_role','private.session_actor()','EXECUTE'),'service_role cannot call the helper');
select pg_temp.assert_true(has_function_privilege('fgc_command','private.session_actor()','EXECUTE'),'fgc_command can call the helper');
rollback;
